<?php require_once 'includes/config.php';$title='Products';$pdo=db();$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$brand=trim($_GET['brand']??'');$min=$_GET['min']??'';$max=$_GET['max']??'';$sort=$_GET['sort']??'featured';$where=['p.status=1'];$args=[];if($q!==''){$where[]='(p.name LIKE ? OR p.brand LIKE ? OR p.sku LIKE ?)';$like='%'.$q.'%';$args=[$like,$like,$like];}if($cat){$where[]='p.category_id=?';$args[]=$cat;}if($brand!==''){$where[]='p.brand=?';$args[]=$brand;}if($min!==''){$where[]='p.price>=?';$args[]=(float)$min;}if($max!==''){$where[]='p.price<=?';$args[]=(float)$max;} $order=['low'=>'p.price ASC','high'=>'p.price DESC','rating'=>'p.rating DESC','new'=>'p.id DESC','featured'=>'p.featured DESC,p.id DESC'][$sort]??'p.featured DESC,p.id DESC';$st=$pdo->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.$order);$st->execute($args);$products=$st->fetchAll();$categories=$pdo->query('SELECT * FROM categories WHERE status=1 ORDER BY name')->fetchAll();$brands=$pdo->query('SELECT DISTINCT brand FROM products WHERE status=1 ORDER BY brand')->fetchAll(PDO::FETCH_COLUMN);require 'includes/header.php';?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="section-title mb-1">Products</h1><p class="text-muted mb-0"><?=count($products)?> product(s) found</p></div></div><div class="row g-4"><aside class="col-lg-3"><div class="bg-white p-3 rounded-4 border sticky-lg-top" style="top:90px"><h5>Filters</h5><form><input type="hidden" name="q" value="<?=e($q)?>"><select name="category" class="form-select mb-2"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="brand" class="form-select mb-2"><option value="">All brands</option><?php foreach($brands as $b):?><option <?=$brand===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select><div class="row g-2"><div class="col"><input name="min" class="form-control" placeholder="Min ₹" value="<?=e($min)?>"></div><div class="col"><input name="max" class="form-control" placeholder="Max ₹" value="<?=e($max)?>"></div></div><select name="sort" class="form-select mt-2"><option value="featured">Featured</option><option value="new">Newest</option><option value="low">Price low-high</option><option value="high">Price high-low</option><option value="rating">Top rated</option></select><button class="btn btn-purple w-100 mt-3">Apply</button><a class="btn btn-outline-purple w-100 mt-2" href="products.php">Clear</a></form></div></aside><section class="col-lg-9"><div class="row row-cols-2 row-cols-md-3 g-3"><?php foreach($products as $p)require 'includes/product-card.php';?></div><?php if(!$products):?><div class="bg-white border rounded-4 p-5 text-center">No products found. Try different filters.</div><?php endif;?></section></div><?php require 'includes/footer.php';?>